// Package mevwatch implements mempool risk detection.
package mevwatch

import (
	"sort"
	"strconv"
)

// Swap is one observed swap in a pending or confirmed transaction.
type Swap struct {
	TxHash   string
	Pool     string
	Trader   string
	In       int64
	Out      int64
	GasPrice int64
	Index    int
}

// Finding is one risk conclusion with the evidence that produced it.
type Finding struct {
	TxHash   string
	Kind     string
	Severity int
	Evidence []string
}

// Detect flags sandwich and displacement patterns around one victim swap.
// It applies the built-in block rules to one transaction, so its conclusion
// matches DetectBlock for the same records: neighbours are the adjacent
// swaps inside the victim's own pool ordered by Index, never swaps from
// other pools and never positions in the input slice. Reordering the input
// or interleaving other pools therefore cannot change the result. The
// victim's pool's last swap is still checked for displacement against its
// predecessor; a victim that is absent or first in its pool has no
// conclusion. The passed slice is never modified.
func Detect(swaps []Swap, victim string) []Finding {
	// Single-transaction detection always runs the built-in version:
	// sandwich severity 3, displacement severity 2 with multiplier 2.
	rules := BuiltinVersion().Rules
	target, ok := findSwap(swaps, victim)
	if !ok {
		return nil
	}
	pool := poolSwaps(swaps, target.Pool)
	pos := -1
	for i, s := range pool {
		if s.TxHash == victim {
			pos = i
			break
		}
	}
	var front, back *Swap
	if pos > 0 {
		front = &pool[pos-1]
	}
	if pos >= 0 && pos+1 < len(pool) {
		back = &pool[pos+1]
	}
	j, hit := judgeVictim(front, target, back, rules)
	if !hit {
		return nil
	}
	if j.kind == "sandwich" {
		return []Finding{{
			TxHash: victim, Kind: j.kind, Severity: j.severity,
			Evidence: []string{
				"front-run by " + front.Trader + " at gas " + strconv.FormatInt(front.GasPrice, 10),
				"back-run by " + back.Trader + " at gas " + strconv.FormatInt(back.GasPrice, 10),
				"victim gas " + strconv.FormatInt(target.GasPrice, 10),
			},
		}}
	}
	return []Finding{{TxHash: victim, Kind: j.kind, Severity: j.severity,
		Evidence: []string{"front gas dominates victim by more than 2x"}}}
}

// findSwap returns the record whose TxHash equals hash. TxHash is unique
// among the valid records replay accepts.
func findSwap(swaps []Swap, hash string) (Swap, bool) {
	for _, s := range swaps {
		if s.TxHash == hash {
			return s, true
		}
	}
	return Swap{}, false
}

// Rank orders findings by severity then hash.
func Rank(findings []Finding) []Finding {
	sorted := append([]Finding(nil), findings...)
	sort.Slice(sorted, func(i, j int) bool {
		if sorted[i].Severity == sorted[j].Severity {
			return sorted[i].TxHash < sorted[j].TxHash
		}
		return sorted[i].Severity > sorted[j].Severity
	})
	return sorted
}

package mevwatch

import (
	"math"
	"sort"
)

// This file holds the single product logic behind both detection entries:
// the single-transaction Detect and the whole-block DetectBlockWithRules
// judge one victim swap against its adjacent neighbours through judgeVictim,
// so a transaction's hit, conclusion kind and severity can never diverge
// between the two. Only the evidence expression differs per entry point.

// judgment is the shared conclusion of the sandwich and displacement rules
// for one victim swap: the conclusion kind and the severity the active rule
// version assigns to it.
type judgment struct {
	kind     string
	severity int
}

// judgeVictim applies rules to one victim swap given its adjacent neighbours
// inside its own pool ordered by Index; front or back is nil at the pool
// edges. An enabled sandwich — the same trader on both sides, different from
// the victim's, with both GasPrices strictly above the victim's — takes
// priority and is then the victim's only conclusion. Otherwise an enabled
// displacement fires when the previous swap's GasPrice strictly exceeds
// Multiplier times the victim's; exact equality does not hit. A victim
// without a preceding swap in its pool has no conclusion, and with both
// rules off neither has anyone.
func judgeVictim(front *Swap, victim Swap, back *Swap, rules RuleSet) (judgment, bool) {
	if rules.Sandwich.Enabled && front != nil && back != nil &&
		front.Trader == back.Trader && front.Trader != victim.Trader &&
		front.GasPrice > victim.GasPrice && back.GasPrice > victim.GasPrice {
		return judgment{kind: "sandwich", severity: rules.Sandwich.Severity}, true
	}
	if rules.Displacement.Enabled && front != nil &&
		gasDominates(front.GasPrice, victim.GasPrice, int64(rules.Displacement.Multiplier)) {
		return judgment{kind: "displacement", severity: rules.Displacement.Severity}, true
	}
	return judgment{}, false
}

// gasDominates reports whether front strictly exceeds victim*multiplier,
// staying correct when victim is zero or near math.MaxInt64.
func gasDominates(front, victim int64, multiplier int64) bool {
	return victim <= math.MaxInt64/multiplier && front > victim*multiplier
}

// poolSwaps returns the swaps of one pool sorted by Index. The result is a
// fresh slice: the caller's records and their order are never modified, so
// input positions and interleaved records of other pools cannot influence
// the judgment.
func poolSwaps(swaps []Swap, pool string) []Swap {
	out := make([]Swap, 0, len(swaps))
	for _, s := range swaps {
		if s.Pool == pool {
			out = append(out, s)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Index < out[j].Index })
	return out
}

