318	}
319	
320	func readArchive(dir string) (archiveData, error) {
321		raw, err := os.ReadFile(filepath.Join(dir, archiveFileName))
322		if errors.Is(err, os.ErrNotExist) {
323			return archiveData{Records: []record{}}, nil
324		}
325		if err != nil {
326			return archiveData{}, err
327		}
328		var data archiveData
329		if err := json.Unmarshal(raw, &data); err != nil {
330			return archiveData{}, fmt.Errorf("archive is corrupted: %w", err)
331		}
332		return data, nil
333	}
334	
335	// writeArchiveAtomic replaces the archive file in one rename, so a crash
336	// can only expose the previous or the next complete commit, never a half
337	// written file.
338	func writeArchiveAtomic(dir string, data archiveData) error {
339		raw, err := json.MarshalIndent(data, "", "  ")
340		if err != nil {
341			return err
342		}
343		tmp := filepath.Join(dir, archiveFileName+".tmp")
344		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
345		if err != nil {
346			return err
347		}
348		if _, err := f.Write(raw); err != nil {
349			f.Close()
350			os.Remove(tmp)
351			return err
352		}
353		if err := f.Sync(); err != nil {
354			f.Close()
355			os.Remove(tmp)
356			return err
357		}
358		if err := f.Close(); err != nil {
359			os.Remove(tmp)
360			return err
361		}
362		if err := os.Rename(tmp, filepath.Join(dir, archiveFileName)); err != nil {
363			os.Remove(tmp)
364			return err
365		}
366		if d, err := os.Open(dir); err == nil {
367			d.Sync()
368			d.Close()
369		}
370		return nil
371	}
372	
373	// lockArchive takes an flock on the archive's lock file. The lock is
374	// released automatically if the process dies, so no stale locks survive.
375	func lockArchive(dir string, how int) (*os.File, error) {
376		f, err := os.OpenFile(filepath.Join(dir, lockFileName), os.O_CREATE|os.O_RDWR, 0o644)
377		if err != nil {
378			return nil, err
379		}
380		if err := syscall.Flock(int(f.Fd()), how); err != nil {
381			f.Close()
382			if errors.Is(err, syscall.EWOULDBLOCK) {
383				return nil, ErrBusy
384			}
385			return nil, err
386		}
387		return f, nil
388	}
389	
390	type parsedBlock struct {
391		line  int
392		block Block
393	}
394	
395	func parseBlocks(r io.Reader) ([]parsedBlock, error) {
396		var out []parsedBlock
397		reader := bufio.NewReader(r)
398		lineNo := 0
399		for {
400			raw, err := reader.ReadBytes('\n')
401			if len(raw) > 0 {
402				lineNo++
403			}
404			if text := strings.TrimSpace(string(raw)); text != "" {
405				block, perr := parseBlock(text)
406				if perr != nil {
407					return nil, &LineError{Line: lineNo, Err: perr}
408				}
409				out = append(out, parsedBlock{line: lineNo, block: block})
410			}
411			if err == io.EOF {
412				return out, nil
413			}
414			if err != nil {
415				return nil, err
416			}
417		}
418	}
419	
420	// ReplayFile imports the line-delimited blocks in inputPath into the
421	// archive at dir and returns one report per distinct block, in order of
422	// first appearance. New blocks are judged under the archive's currently
423	// enabled rule version.
424	func ReplayFile(inputPath, dir string) ([]Report, error) {
425		return replayFile(inputPath, dir, "")
426	}
427	
428	// ReplayFileWithVersion is ReplayFile under an explicitly registered rule
429	// version instead of the archive's enabled one.
430	func ReplayFileWithVersion(inputPath, dir, versionID string) ([]Report, error) {
431		if versionID == "" {
432			return nil, errors.New("version id must not be empty")
433		}
434		return replayFile(inputPath, dir, versionID)
435	}
436	
437	func replayFile(inputPath, dir, versionID string) ([]Report, error) {
438		f, err := os.Open(inputPath)
439		if err != nil {
440			return nil, err
441		}
442		defer f.Close()
443		return doReplay(f, dir, versionID)
444	}
445	
446	// Replay parses, validates and archives blocks from r under the archive's
447	// currently enabled rule version. Every line is checked before anything is
448	// written; any failure leaves the archive untouched. New reports are
449	// committed together in a single atomic write.
450	func Replay(input io.Reader, dir string) ([]Report, error) {
451		return doReplay(input, dir, "")
452	}
453	
454	// ReplayWithVersion is Replay under an explicitly registered rule version
455	// instead of the archive's enabled one.
456	func ReplayWithVersion(input io.Reader, dir, versionID string) ([]Report, error) {
457		if versionID == "" {
458			return nil, errors.New("version id must not be empty")
459		}
460		return doReplay(input, dir, versionID)
461	}
462	
463	func doReplay(input io.Reader, dir, versionID string) ([]Report, error) {
464		parsed, err := parseBlocks(input)
465		if err != nil {
466			return nil, err
467		}
468	
469		// Collapse repeated identities within this file, keeping first
470		// appearance order; conflicting content rejects the whole file.
471		type occurrence struct {
472			block Block
473			line  int
474		}
475		order := []occurrence{}
476		firstSeen := make(map[blockID]int)
477		for _, p := range parsed {
478			id := blockID{p.block.ChainID, p.block.BlockHash}
479			if first, ok := firstSeen[id]; ok {
480				if !sameContent(order[first].block.BlockNumber, order[first].block.Swaps, p.block) {
481					return nil, &LineError{Line: p.line, Err: fmt.Errorf(
482						"block %s/%s conflicts with line %d", id.chainID, id.blockHash, order[first].line)}
483				}
484				continue
485			}
486			firstSeen[id] = len(order)
487			order = append(order, occurrence{block: p.block, line: p.line})
488		}
489	
490		if err := os.MkdirAll(dir, 0o755); err != nil {
491			return nil, err
492		}
493		lock, err := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
494		if err != nil {
495			return nil, err
496		}
497		defer lock.Close()
498	
499		data, err := readArchive(dir)
500		if err != nil {
501			return nil, err
502		}
503		// Resolve the version once, while the exclusive lock is held: every
504		// new block in this run is judged under the same rules even if another
505		// process enables a different version right after we finish.
506		version, err := resolveReplayVersion(data, versionID)
507		if err != nil {
508			return nil, err
509		}
510		archived := make(map[blockID]int, len(data.Records))
511		for i, rec := range data.Records {
512			archived[rec.id()] = i
513		}
514	
515		reports := make([]Report, 0, len(order))
516		changed := false
517		for _, occ := range order {
518			id := blockID{occ.block.ChainID, occ.block.BlockHash}
519			if idx, ok := archived[id]; ok {
520				rec := data.Records[idx]
521				if !sameContent(rec.BlockNumber, rec.Swaps, occ.block) {
522					return nil, &LineError{Line: occ.line, Err: fmt.Errorf(
523						"block %s/%s conflicts with the archived record", id.chainID, id.blockHash)}
524				}
525				// Identical re-import: return the original report, add nothing.
526				reports = append(reports, rec.report())
527				continue
528			}
529			rec := record{
530				ChainID:     occ.block.ChainID,
531				BlockHash:   occ.block.BlockHash,
532				BlockNumber: occ.block.BlockNumber,
533				Swaps:       occ.block.Swaps,
534				Findings:    DetectBlockWithRules(occ.block.Swaps, version.Rules),
535				Version:     &version,
536			}
537			archived[id] = len(data.Records)
538			data.Records = append(data.Records, rec)
539			reports = append(reports, rec.report())
540			changed = true
541		}
542		if changed {
543			if err := writeArchiveAtomic(dir, data); err != nil {
544				return nil, err
545			}
546		}
547		return reports, nil
548	}
549	
550	// resolveReplayVersion picks the rule version for one replay run: the
551	// explicitly requested one, or the archive's currently enabled version.
552	func resolveReplayVersion(data archiveData, versionID string) (RuleVersion, error) {
553		if versionID != "" {
554			return findVersion(data, versionID)
555		}
556		return data.enabledVersion()
557	}
558	
559	// Query returns the archived report for one block identity. It only reads
560	// the archive; the original input file is not needed.
561	func Query(dir, chainID, blockHash string) (Report, error) {
562		if _, err := os.Stat(dir); err != nil {
563			if errors.Is(err, os.ErrNotExist) {
564				return Report{}, ErrUnknownBlock
565			}
566			return Report{}, err
567		}
568		lock, err := lockArchive(dir, syscall.LOCK_SH)
569		if err != nil {
570			return Report{}, err
571		}
572		defer lock.Close()
573	
574		data, err := readArchive(dir)
575		if err != nil {
576			return Report{}, err
577		}
578		for _, rec := range data.Records {
579			if rec.ChainID == chainID && rec.BlockHash == blockHash {
580				return rec.report(), nil
581			}
582		}
583		return Report{}, ErrUnknownBlock
584	}
