23		// archived: sandwich severity 4, displacement severity 1 with
24		// multiplier 3.
25		archivedVersionSpec = `{"id":"archA","rules":{"sandwich":{"enabled":true,"severity":4},"displacement":{"enabled":true,"severity":1,"multiplier":3}}}`
26		// enabledVersion is enabled in the archive afterwards but must never
27		// leak into either side of a comparison. Its judgments are markedly
28		// different: sandwich severity 5, displacement severity 5 with
29		// multiplier 4.
