32		// disabled, displacement severity 4 with the builtin multiplier 2.
33		candidateVersionSpec = `{"id":"candC","rules":{"sandwich":{"enabled":false,"severity":3},"displacement":{"enabled":true,"severity":4,"multiplier":2}}}`
34		// twinVersion carries the builtin parameters under another id, so a
35		// comparison produces identical conclusions and an empty diff.
36		twinVersionSpec = `{"id":"twin","rules":{"sandwich":{"enabled":true,"severity":3},"displacement":{"enabled":true,"severity":2,"multiplier":2}}}`
