39	// cmpSwap builds one swap record map; In and Out are fixed because the
40	// detection rules never read them, while every numeric field is explicit.
41	func cmpSwap(tx, pool, trader string, gas int64, index int) map[string]any {
42		return map[string]any{
43			"TxHash": tx, "Pool": pool, "Trader": trader,
44			"In": 1, "Out": 1, "GasPrice": gas, "Index": index,
45		}
