82				cmpSwap("0xd0f", "p4", "w", 25, 8),
83				cmpSwap("0xd0v", "p4", "u", 10, 9),
84				cmpSwap("0xe0f", "p5", "bot", 15, 10),
85				cmpSwap("0xe0v", "p5", "user", 10, 11),
86				cmpSwap("0xe0b", "p5", "bot", 11, 12),
87			),
