411			`{"TxHash":"0v","Pool":"p1","Trader":"user","In":5,"Out":4,"GasPrice":10,"Index":1},` +
412			`{"TxHash":"0b","Pool":"p1","Trader":"bot","In":3,"Out":5,"GasPrice":80,"Index":2}],` +
413			`"findings":[{"kind":"sandwich","severity":3,"txHash":"0v","evidence":[` +
414			`{"TxHash":"0f","Pool":"p1","Trader":"bot","In":7,"Out":6,"GasPrice":90,"Index":0},` +
415			`{"TxHash":"0v","Pool":"p1","Trader":"user","In":5,"Out":4,"GasPrice":10,"Index":1},` +
416			`{"TxHash":"0b","Pool":"p1","Trader":"bot","In":3,"Out":5,"GasPrice":80,"Index":2}]}]}]}`
417		if err := os.WriteFile(filepath.Join(dir, archiveFileName), []byte(legacy), 0o644); err != nil {
418			t.Fatal(err)
419		}
420		register(t, dir, candidateVersionSpec)
421		result, err := Compare(dir, "1", "0old", "candC")
422		if err != nil {
423			t.Fatal(err)
424		}
425		// Archived side is explained as the built-in version with all params.
426		if !reflect.DeepEqual(result.OriginalVersion, BuiltinVersion()) {
427			t.Fatalf("original version = %+v, want builtin", result.OriginalVersion)
428		}
429		if result.OriginalVersion.Rules.Displacement.Multiplier != 2 ||
430			result.OriginalVersion.Rules.Sandwich.Severity != 3 {
431			t.Fatalf("builtin parameters incomplete: %+v", result.OriginalVersion)
432		}
433		if len(result.OriginalFindings) != 1 || result.OriginalFindings[0].Kind != "sandwich" {
434			t.Fatalf("legacy findings damaged: %+v", result.OriginalFindings)
435		}
436		// Candidate side is judged under candC: sandwich off, displacement
437		// sev4 with multiplier 2 (90 > 20).
438		if len(result.ComparedFindings) != 1 ||
439			result.ComparedFindings[0].Kind != "displacement" || result.ComparedFindings[0].Severity != 4 {
440			t.Fatalf("candidate re-judgment wrong: %+v", result.ComparedFindings)
441		}
442		if len(result.Swaps) != 3 || result.Swaps[0].In != 7 || result.Swaps[2].Out != 5 {
443			t.Fatalf("legacy swap records damaged: %+v", result.Swaps)
444		}
445	}
446	
447	func TestCompareRegressionReadOnly(t *testing.T) {
448		dir := setupCompareArchive(t)
449		before, err := os.ReadFile(filepath.Join(dir, archiveFileName))
450		if err != nil {
451			t.Fatal(err)
452		}
453	
454		run := func(chain, hash, version string) {
455			t.Helper()
456			_, _ = Compare(dir, chain, hash, version)
457		}
458		// Successful comparisons, including the decoy identities...
459		run("1", "0xblk", "candC")
460		run("1", "0xblk", BuiltinVersionID)
461		run("1", "0xother", "candC")
462		run("2", "0xblk", "candC")
463		// ...and every failure shape leave the archive file byte-identical.
464		run("1", "0xmissing", "candC")
465		run("1", "0xblk", "ghost")
466		run("9", "0xblk", "candC")
467	
468		after, err := os.ReadFile(filepath.Join(dir, archiveFileName))
469		if err != nil {
470			t.Fatal(err)
471		}
472		if !reflect.DeepEqual(before, after) {
473			t.Fatalf("compare changed the archive:\nbefore=%s\nafter =%s", before, after)
474		}
475	
476		// The archived report keeps archA conclusions; the enabled version is
477		// still liveB; failed comparisons changed neither.
478		report, err := Query(dir, "1", "0xblk")
479		if err != nil {
480			t.Fatal(err)
481		}
482		if report.Version.ID != "archA" || len(report.Findings) != 3 {
483			t.Fatalf("archived report changed: %+v", report)
484		}
485		_, enabled, err := ListVersions(dir)
486		if err != nil {
487			t.Fatal(err)
488		}
489		if enabled != "liveB" {
490			t.Fatalf("enabled version = %q, want liveB", enabled)
491		}
492	}
493	
494	func TestCompareRegressionDecoysDoNotMixIn(t *testing.T) {
495		dir := setupCompareArchive(t)
496		main, err := Compare(dir, "1", "0xblk", "candC")
497		if err != nil {
498			t.Fatal(err)
499		}
500		other, err := Compare(dir, "1", "0xother", "candC")
501		if err != nil {
502			t.Fatal(err)
503		}
504		chain2, err := Compare(dir, "2", "0xblk", "candC")
505		if err != nil {
506			t.Fatal(err)
507		}
508		if other.ChainID != "1" || other.BlockHash != "0xother" || len(other.Swaps) != 2 {
509			t.Fatalf("same-height other block scoping wrong: %+v", other)
510		}
511		if chain2.ChainID != "2" || chain2.BlockHash != "0xblk" || len(chain2.Swaps) != 2 {
512			t.Fatalf("other-chain block scoping wrong: %+v", chain2)
513		}
514		if chain2.Swaps[0].TxHash != "0xqq1" || main.Swaps[0].TxHash != "0xa0f" {
515			t.Fatalf("swap records leaked across chains: main=%+v chain2=%+v", main.Swaps, chain2.Swaps)
516		}
517		// Findings from one identity never appear under another.
518		all := append(append([]ReportFinding{}, main.OriginalFindings...), other.OriginalFindings...)
519		all = append(all, chain2.OriginalFindings...)
520		for _, f := range all {
521			if strings.HasPrefix(f.TxHash, "0xzz") || strings.HasPrefix(f.TxHash, "0xqq") {
522				t.Fatalf("decoy conclusion leaked into another block's set: %+v", all)
523			}
524		}
525		// Determinism: repeated queries produce identical JSON.
526		again, err := Compare(dir, "1", "0xblk", "candC")
527		if err != nil {
528			t.Fatal(err)
529		}
530		b1, _ := json.Marshal(main)
531		b2, _ := json.Marshal(again)
532		if string(b1) != string(b2) {
533			t.Fatalf("compare is not deterministic:\n%s\n%s", b1, b2)
534		}
535		// Sanity: findings inside each result stay severity desc / hash asc.
536		for _, r := range []CompareResult{main, other, chain2} {
537			if !sort.SliceIsSorted(r.OriginalFindings, func(i, j int) bool {
538				a, b := r.OriginalFindings[i], r.OriginalFindings[j]
539				if a.Severity != b.Severity {
540					return a.Severity > b.Severity
541				}
542				return a.TxHash < b.TxHash
543			}) {
544				t.Fatalf("original findings not severity/hash ordered: %+v", r.OriginalFindings)
545			}
546		}
547	}
