// findIntactVersion resolves id like findVersion and then proves the
// version's stored archive document still satisfies every registration
// rule, re-validating the raw bytes with the same parser registrations
// pass. The decoded struct alone cannot do this: a missing enabled,
// severity or multiplier field unmarshals as the zero value and is
// indistinguishable from an explicitly declared one. An explicitly
// declared false or any in-range value is valid; a missing or null field,
// a wrong type or an out-of-range number makes the version corrupt, and
// the failure names the version and the offending rule or field. The
// built-in version is constructed in code and always intact. raw must be
// the exact archive file bytes data was decoded from.
func findIntactVersion(raw []byte, data archiveData, id string) (RuleVersion, error) {
	if _, err := findVersion(data, id); err != nil {
		return RuleVersion{}, err
	}
	if id == BuiltinVersionID {
		return BuiltinVersion(), nil
	}
	var envelope struct {
		Versions []json.RawMessage `json:"versions"`
	}
	if err := json.Unmarshal(raw, &envelope); err != nil {
		return RuleVersion{}, fmt.Errorf("archive is corrupted: %w", err)
	}
	for _, entry := range envelope.Versions {
		var meta struct {
			ID string `json:"id"`
		}
		if err := json.Unmarshal(entry, &meta); err != nil || meta.ID != id {
			continue
		}
		v, err := ParseRuleVersion(entry)
		if err != nil {
			return RuleVersion{}, fmt.Errorf("%w: %s: %w", ErrCorruptVersion, id, err)
		}
		return v, nil
	}
	// findVersion matched this id in the decoded data, so the raw document
	// must carry it too; reaching here means the two disagree.
	return RuleVersion{}, fmt.Errorf("%w: %s: version document is not a JSON object", ErrCorruptVersion, id)
}

